module main

import math

fn nth_prime(n int) !int {
	if n < 1 {
		return error('n must be greater than 0')
	}

	mut n_primes := 1
	mut i := 3

	for n_primes < n {
		if is_prime(i) {
			n_primes++
		}
		i++
	}
	return i - 1
}

fn is_prime(n int) bool {
	for m in 2 .. int(math.ceil(math.sqrt(n))) + 1 {
		if n % m == 0 {
			return false
		}
	}
	return true
}

test_code:
module main

fn test_first_prime() {
	assert nth_prime(1)! == 2
}

fn test_second_prime() {
	assert nth_prime(2)! == 3
}

fn test_sixth_prime() {
	assert nth_prime(6)! == 13
}

fn test_big_prime() {
	assert nth_prime(10001)! == 104743
}

fn test_zeroth_prime() {
	if res := nth_prime(0) {
		assert false, 'there is no zeroth prime'
	} else {
		assert err.msg() == 'n must be greater than 0'
	}
}
